SELECT 
FROM fbs_connector_binding b
INNER JOIN fbs_enterprise_member m
    ON m.id = b.member_id
   AND m.enterprise_id = b.enterprise_id
   AND m.user_id = b.user_id
   AND m.status = 1
   AND m.del_flag = '0'
INNER JOIN fbs_enterprise e
    ON e.id = b.enterprise_id
   AND e.status = 1
   AND e.del_flag = '0'
WHERE b.enterprise_id = #{tenantId}
  AND b.member_id = #{memberId}
  AND b.user_id = #{userId}
  AND b.product_code = #{productCode}
  AND b.source_code = #{sourceCode}
  AND b.connector_code = #{connectorCode}
LIMIT 1

