mapper.update:
UPDATE fbs_connector_binding
SET status = #{binding.status},
    revoked_at = #{binding.revokedAt},
    version = version + 1,
    updated_at = NOW(3)
WHERE id = #{binding.id}
  AND enterprise_id = #{binding.tenantId}
  AND member_id = #{binding.memberId}
  AND user_id = #{binding.userId}
  AND product_code = #{binding.productCode}
  AND source_code = #{binding.sourceCode}
  AND connector_code = #{binding.connectorCode}
  AND status = 'ACTIVE'
  AND version = #{expectedVersion}

UPDATE fbs_connector_binding
SET issuer_uri = #{binding.issuerUri},
    resource_uri = #{binding.resourceUri},
    client_id = #{binding.clientId},
    principal_subject_digest = #{binding.principalSubjectDigest},
    status = 'ACTIVE',
    verification_method = #{binding.verificationMethod},
    evidence_digest = #{binding.evidenceDigest},
    verified_at = #{binding.verifiedAt},
    last_seen_at = #{binding.lastSeenAt},
    valid_until = #{binding.validUntil},
    revoked_at = NULL,
    version = version + 1,
    updated_at = #{binding.verifiedAt}
WHERE id = #{binding.id}
  AND binding_id = #{binding.bindingId}
  AND enterprise_id = #{binding.tenantId}
  AND member_id = #{binding.memberId}
  AND user_id = #{binding.userId}
  AND product_code = #{binding.productCode}
  AND source_code = #{binding.sourceCode}
  AND connector_code = #{binding.connectorCode}
  AND status IN ('ACTIVE', 'REVOKED', 'COMPROMISED')
  AND version = #{expectedVersion}

mapper.select:
SELECT id, enterprise_id, member_id, product_code, metric_code, bucket_date,
       daily_limit, reserved_count, used_count, version
FROM fbs_usage_budget
WHERE enterprise_id = #{tenantId}
  AND member_id = #{memberId}
  AND product_code = #{productCode}
  AND metric_code = #{metricCode}
  AND bucket_date = #{bucketDate,jdbcType=DATE}
LIMIT 1

mapper.update:
UPDATE fbs_usage_budget
SET daily_limit = #{dailyLimit},
    reserved_count = reserved_count + 1,
    version = version + 1,
    updated_at = NOW()
WHERE enterprise_id = #{tenantId}
  AND member_id = #{memberId}
  AND product_code = #{productCode}
  AND metric_code = #{metricCode}
  AND bucket_date = #{bucketDate,jdbcType=DATE}
  AND used_count + reserved_count < #{dailyLimit}

